<script setup lang="ts">
import { checkpointDistanceText } from '../../checkpointDistance';
import { computed, ref, watch } from 'vue';
import { useRaceRefresh } from '../../Composables/useRaceRefresh';
import { Head, Link, usePage, router } from '@inertiajs/vue3';
import AppLayout from '../../Layouts/AppLayout.vue';
import { formatDuration, bibLabel } from '../../lib';
import type { Checkpoint, PageProps, Race } from '../../types';
interface Row { id:number;place:number|null;result_status:string; bib_number:string|null; type:string; name:string; category?:string; members:Array<{discipline:string;name:string}>; splits:Array<{checkpoint:string;elapsed_ms:number|null;split_ms:number|null}>; total_ms:number|null; finished:boolean }
const props = defineProps<{ race:Race & {checkpoints:Checkpoint[]}; results:Row[]; categories:string[];filters:{type?:string;category?:string;status?:string} }>();
const filters=ref({type:props.filters.type??'',category:props.filters.category??'',status:props.filters.status??''});
watch(filters,()=>router.get(`/races/${props.race.id}/results`,filters.value,{preserveState:true,preserveScroll:true,replace:true}),{deep:true});
const exportQuery=computed(()=>new URLSearchParams(filters.value).toString());
const page = usePage<PageProps>();
const timingCheckpoints = computed(() => props.race.checkpoints.filter(cp => cp.kind !== 'start'));
useRaceRefresh(() => ['race', 'results']);
</script>
<template><Head :title="`${race.name} results`"/><AppLayout :title="`${race.name} · Results`"><div class="mb-5 flex flex-wrap gap-2"><a v-if="page.props.auth.user?.role!=='athlete'" :href="`/races/${race.id}/results.csv?${exportQuery}`" class="btn-secondary">Export CSV</a><a v-if="page.props.auth.user?.role!=='athlete'" :href="`/races/${race.id}/results.xlsx?${exportQuery}`" class="btn-primary">Export XLSX</a></div><section class="panel-pad mb-4 grid gap-3 sm:grid-cols-3" aria-label="Result filters"><label class="label">Entry type<select v-model="filters.type" class="field"><option value="">All types</option><option value="solo">Solo</option><option value="relay">Relay</option></select></label><label class="label">Category<select v-model="filters.category" class="field"><option value="">All categories</option><option v-for="category in categories" :key="category">{{ category }}</option></select></label><label class="label">Result status<select v-model="filters.status" class="field"><option value="">All statuses</option><option>FINISHED</option><option>IN PROGRESS</option><option>DNS</option><option>DNF</option><option>DSQ</option></select></label><p class="muted text-xs sm:col-span-3">Places apply to the selected group. Equal total milliseconds share a place (1, 1, 3). DNS, DNF and DSQ keep their timings but receive no place. Exports use these filters.</p></section><div class="panel overflow-x-auto"><table class="min-w-full text-left text-sm"><thead class="bg-slate-900 text-xs uppercase tracking-wide text-slate-400"><tr><th class="p-3">Place</th><th class="p-3">Bib</th><th class="min-w-56 p-3">Participant</th><th v-for="cp in timingCheckpoints" :key="cp.id" class="whitespace-nowrap p-3">{{ cp.name }}<div class="mt-1 text-xs font-normal normal-case tracking-normal">{{ checkpointDistanceText(race, cp) }}</div></th><th class="p-3">Total</th></tr></thead><tbody><tr v-for="(row,index) in results" :key="row.id" class="border-t border-slate-800"><td class="p-3 font-bold">{{ row.place ?? '—' }}</td><td class="p-3 font-mono font-bold">{{ bibLabel(row.bib_number) }}</td><td class="p-3"><div class="font-semibold">{{ row.name }}</div><div class="text-xs muted">{{ row.category }} · {{ row.result_status }}</div><div v-if="row.type==='relay'" class="mt-1 text-xs muted">{{ row.members.map(m=>`${m.discipline}: ${m.name}`).join(' · ') }}</div></td><td v-for="split in row.splits" :key="split.checkpoint" class="p-3 font-mono"><div>{{ formatDuration(split.elapsed_ms) }}</div><div v-if="split.split_ms!==null" class="text-xs text-slate-500">split {{ formatDuration(split.split_ms) }}</div></td><td class="p-3 font-mono text-base font-bold" :class="row.finished?'text-emerald-300':'text-slate-500'">{{ formatDuration(row.total_ms) }}</td></tr><tr v-if="!results.length"><td :colspan="timingCheckpoints.length+4" class="p-8 text-center muted">No participants yet.</td></tr></tbody></table></div></AppLayout></template>
